From dfaf941ad65e381b8151efea886d48790f83f9f6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:15:02 +0100
Subject: [PATCH] applets/taskmanager: scroll tasks instead of shrinking them
 to nothing

When the panel was crowded, tasks shrank with no lower limit and their
icons became unusable. Tasks now keep their icon size and scroll, with
faded edges, keeping the active or attention-seeking task in view.

BUG: 447603
---
 applets/taskmanager/qml/MouseHandler.qml |  11 +-
 applets/taskmanager/qml/Task.qml         |  25 +++-
 applets/taskmanager/qml/main.qml         | 138 ++++++++++++++++++++++-
 3 files changed, 163 insertions(+), 11 deletions(-)

diff --git a/applets/taskmanager/qml/MouseHandler.qml b/applets/taskmanager/qml/MouseHandler.qml
index 2fd85860c2..d7ea22a439 100644
--- a/applets/taskmanager/qml/MouseHandler.qml
+++ b/applets/taskmanager/qml/MouseHandler.qml
@@ -37,15 +37,13 @@ DropArea {
             return;
         }

-        // RtL horizontal TaskLists do not include the spacer (which are initial in this
-        // configuration), if any, but the mouse event coordinates do. We need to subtract
-        // them, or we end thinking we're dragging way right of where we actually are.
-        const rtlSpacerAdjustment = target.LayoutMirroring.enabled ? tasks.width - target.width : 0;
         let above;
         if (isGroupDialog) {
             above = target.itemAt(event.x, event.y);
         } else {
-            above = target.childAt(event.x - rtlSpacerAdjustment, event.y);
+            // The TaskList can be offset by RtL spacers and by scrolling.
+            const pos = mapToItem(target, event.x, event.y);
+            above = target.childAt(pos.x, pos.y);
         }

         if (!above) {
@@ -181,7 +179,8 @@ DropArea {
                 rotation += 15;
                 increment--;
             }
-            const anchor = dropArea.target.childAt(event.x, event.y);
+            const pos = dropArea.isGroupDialog ? Qt.point(event.x, event.y) : dropArea.mapToItem(dropArea.target, event.x, event.y);
+            const anchor = dropArea.target.childAt(pos.x, pos.y);
             if (Plasmoid.configuration.wheelEnabled === 3) {
                 const loudest = anchor?.audioStreams?.reduce((loudest, stream) => Math.max(loudest, stream.volume), 0)
                 const step = (pulseAudio.item.normalVolume - pulseAudio.item.minimalVolume) * pulseAudio.item.globalConfig.volumeStep / 100;
