diff --git a/applets/taskmanager/qml/main.qml b/applets/taskmanager/qml/main.qml
index d0a62d21bc..2a995025f0 100644
--- a/applets/taskmanager/qml/main.qml
+++ b/applets/taskmanager/qml/main.qml
@@ -6,6 +6,7 @@
 pragma ComponentBehavior: Bound

 import QtQuick
+import QtQuick.Effects
 import QtQuick.Layouts

 import org.kde.plasma.plasmoid
@@ -460,8 +461,114 @@ PlasmoidItem {
                 top: parent.top
             }

-            height: taskList.height
-            width: taskList.width
+            height: Math.min(taskList.height, tasks.height)
+            width: Math.min(taskList.width, tasks.width)
+            clip: overflow > 0
+
+            // When the tasks don't fit even at their minimum size, scroll them
+            // instead of shrinking them further.
+            readonly property real overflow: tasks.vertical ? taskList.height - tasks.height : taskList.width - tasks.width
+            property real scrollPosition: 0
+            readonly property real scrollOffset: Math.max(0, Math.min(scrollPosition, overflow))
+            readonly property bool clippedAtStart: overflow > 0 && (tasks.vertical ? taskList.y < 0 : taskList.x < 0)
+            readonly property bool clippedAtEnd: overflow > 0 && (tasks.vertical ? taskList.y + taskList.height > height : taskList.x + taskList.width > width)
+
+            // The task to keep in view until the user scrolls
+            property Item scrollTarget
+
+            function showTask(task: Item): void {
+                scrollTarget = task;
+                Qt.callLater(scrollToTarget);
+            }
+
+            function scrollToTarget(): void {
+                if (!scrollTarget || overflow <= 0) {
+                    return;
+                }
+                const start = tasks.vertical ? scrollTarget.y : scrollTarget.x;
+                const end = start + (tasks.vertical ? scrollTarget.height : scrollTarget.width);
+                const visibleStart = tasks.vertical ? -taskList.y : -taskList.x;
+                const visibleEnd = visibleStart + (tasks.vertical ? height : width);
+                let delta = 0;
+                if (start < visibleStart) {
+                    delta = start - visibleStart;
+                } else if (end > visibleEnd) {
+                    delta = Math.min(end - visibleEnd, start - visibleStart);
+                }
+                // A mirrored TaskList is anchored to the right, so it scrolls the other way
+                const mirrored = !tasks.vertical && taskList.LayoutMirroring.enabled;
+                scrollPosition = Math.max(0, Math.min(scrollOffset + (mirrored ? -delta : delta), overflow));
+            }
+
+            function scrollBy(event): void {
+                let delta = event.pixelDelta.y || event.pixelDelta.x;
+                if (delta === 0) {
+                    const taskSize = tasks.vertical ? TaskManagerApplet.LayoutMetrics.preferredMinHeight() : TaskManagerApplet.LayoutMetrics.preferredMinLauncherWidth();
+                    delta = (event.angleDelta.y || event.angleDelta.x) / 120 * taskSize;
+                }
+                scrollTarget = null;
+                scrollPosition = Math.max(0, Math.min(scrollOffset - delta, overflow));
+            }
+
+            onOverflowChanged: Qt.callLater(scrollToTarget)
+
+            Connections {
+                target: tmf.scrollTarget
+                function onXChanged(): void {
+                    Qt.callLater(tmf.scrollToTarget);
+                }
+                function onYChanged(): void {
+                    Qt.callLater(tmf.scrollToTarget);
+                }
+                function onWidthChanged(): void {
+                    Qt.callLater(tmf.scrollToTarget);
+                }
+                function onHeightChanged(): void {
+                    Qt.callLater(tmf.scrollToTarget);
+                }
+            }
+
+            // The vertical wheel keeps the configured scrolling behavior and needs Shift
+            // to scroll the tasks; horizontal scrolling always scrolls them.
+            WheelHandler {
+                acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
+                acceptedModifiers: Plasmoid.configuration.wheelEnabled === 0 ? Qt.KeyboardModifierMask : Qt.ShiftModifier
+                enabled: tmf.overflow > 0
+                onWheel: event => tmf.scrollBy(event)
+            }
+            WheelHandler {
+                acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
+                orientation: Qt.Horizontal
+                enabled: tmf.overflow > 0
+                onWheel: event => tmf.scrollBy(event)
+            }
+
+            // Fade the tasks out at the edges where some are scrolled out of view
+            layer.enabled: clippedAtStart || clippedAtEnd
+            layer.effect: MultiEffect {
+                maskEnabled: true
+                maskSource: fadeMask
+                maskThresholdMin: 0.5
+                maskSpreadAtMin: 1
+            }
+
+            Rectangle {
+                id: fadeMask
+
+                readonly property real fadeLength: Math.min(Kirigami.Units.gridUnit, (tasks.vertical ? height : width) / 4) / (tasks.vertical ? height : width)
+
+                width: tmf.width
+                height: tmf.height
+                visible: false
+                layer.enabled: true
+                gradient: Gradient {
+                    orientation: tasks.vertical ? Gradient.Vertical : Gradient.Horizontal
+                    GradientStop { position: 0; color: tmf.clippedAtStart ? "transparent" : "white" }
+                    GradientStop { position: fadeMask.fadeLength; color: "white" }
+                    GradientStop { position: 1 - fadeMask.fadeLength; color: "white" }
+                    GradientStop { position: 1; color: tmf.clippedAtEnd ? "transparent" : "white" }
+                }
+            }

             TaskList {
                 id: taskList
@@ -470,6 +577,8 @@ PlasmoidItem {
                 anchors {
                     left: parent.left
                     top: parent.top
+                    leftMargin: tasks.vertical ? 0 : -tmf.scrollOffset
+                    topMargin: tasks.vertical ? -tmf.scrollOffset : 0
                 }

                 count: tasksModel.count
@@ -495,6 +604,14 @@ PlasmoidItem {
                         }, 0);
                     return Math.round(totalMaxHeight / heightOccupation);
                 }
+                readonly property real contentMinimumWidth: {
+                    const totalMinWidth = children.reduce((accumulator, child) => accumulator + child.Layout.minimumWidth, 0);
+                    return Math.ceil(totalMinWidth / widthOccupation) || 0;
+                }
+                readonly property real contentMinimumHeight: {
+                    const totalMinHeight = children.reduce((accumulator, child) => accumulator + child.Layout.minimumHeight, 0);
+                    return Math.ceil(totalMinHeight / heightOccupation) || 0;
+                }
                 width: {
                     if (tasks.shouldShrinkToZero) {
                         return 0;
@@ -502,7 +619,7 @@ PlasmoidItem {
                     if (tasks.vertical) {
                         return tasks.width * Math.min(1, widthOccupation);
                     } else {
-                        return Math.min(tasks.width, Layout.maximumWidth);
+                        return Math.max(Math.min(tasks.width, Layout.maximumWidth), contentMinimumWidth);
                     }
                 }
                 height: {
@@ -510,7 +627,7 @@ PlasmoidItem {
                         return 0;
                     }
                     if (tasks.vertical) {
-                        return Math.min(tasks.height, Layout.maximumHeight);
+                        return Math.max(Math.min(tasks.height, Layout.maximumHeight), contentMinimumHeight);
                     } else {
                         return tasks.height * Math.min(1, heightOccupation);
                     }
@@ -535,6 +652,14 @@ PlasmoidItem {
                     delegate: Task {
                         tasksRoot: tasks
                     }
+
+                    onItemAdded: (index, item) => {
+                        // Show launching apps; new windows are shown when they
+                        // become active or demand attention.
+                        if ((item as Task).model.IsStartup) {
+                            tmf.showTask(item);
+                        }
+                    }
                 }
             }
         }
@@ -561,6 +686,11 @@ PlasmoidItem {
         }
     }

+    // Scrolls the task into view when the tasks don't all fit
+    function showTask(task: Item): void {
+        tmf.showTask(task);
+    }
+
     function activateTaskAtIndex(index: int): void {
         const task = taskRepeater.itemAt(index) as Task;
         if (task) {
